  { name: 'CI/CD', pattern: /\bci\s*\/\s*cd\b/i },
  { name: 'Linux', pattern: /\b(?:linux|unix)\b/i },

  // AI & Data Science
  { name: 'Machine Learning', pattern: /\bmachine\s+learning\b/i },
