function extractSkillsFromText(text = '') {
  if (!text || typeof text !== 'string') return [];
  const found = new Set();
  for (const { name, pattern } of CANONICAL_SKILL_PATTERNS) {
    if (pattern.test(text)) {
      found.add(name);
    }
  }
  return Array.from(found);
}

function extractRequirementsFromText(text = '') {
  if (!text || typeof text !== 'string') return [];
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const requirements = [];

  let inQualificationSection = false;
  let sectionIsPreferred = false;

  const qualSectionRegex = /^(?:qualifications|requirements|what we are looking for|basic qualifications|minimum qualifications|preferred qualifications|eligibility criteria|skills required|what you'?ll need)/i;
  const preferredSectionRegex = /^(?:preferred qualifications|nice to have|bonus points|good to have|preferred skills)/i;
  const endSectionRegex = /^(?:about us|about the company|what we offer|benefits|perks|compensation|equal opportunity|eeo|how to apply)/i;

  for (const rawLine of lines) {
    const stripped = rawLine.replace(/^[#*_~<>\s\-\d\.]+|[#*_~<>:\s]+$/g, '').trim();
    if (endSectionRegex.test(stripped)) {
      inQualificationSection = false;
      continue;
    }

    if (qualSectionRegex.test(stripped)) {
      inQualificationSection = true;
      sectionIsPreferred = preferredSectionRegex.test(stripped);
      continue;
    }

    if (inQualificationSection) {
      // Look for bullet points or criteria lines
      const isBullet = /^[•\-\*\d+\.]\s+/.test(rawLine);
      const cleanLine = rawLine.replace(/^[\s#*•\-\d\.]+\s*/, '').replace(/<[^>]+>/g, '').trim();

      if (cleanLine.length < 5 || cleanLine.length > 300) continue;

      // Determine if mandatory
      const isExplicitPreferred = /\b(?:preferred|plus|bonus|nice to have|optional|helpful)\b/i.test(cleanLine);
      const isExplicitMandatory = /\b(?:must|required|mandatory|essential|minimum|at least|only)\b/i.test(cleanLine);
      const mandatory = !sectionIsPreferred && (isExplicitMandatory || (!isExplicitPreferred && isBullet));

      // Determine kind
      let kind = 'other';
      if (/\b(?:degree|b\.?tech|b\.?e\.?|m\.?tech|bca|mca|bachelor|master|diploma)\b/i.test(cleanLine)) kind = 'degree';
      else if (/\b(?:cgpa|gpa|percentage|marks)\b/i.test(cleanLine)) kind = 'cgpa';
      else if (/\b(?:batch|graduat(?:ing|ion)|class of|passout)\b/i.test(cleanLine)) kind = 'academic_year';
      else if (/\b(?:computer science|information technology|electronics|mechanical|branch)\b/i.test(cleanLine)) kind = 'branch';
      else if (/\b(?:location|relocat|remote|hybrid|office|bangalore|bengaluru|pune|hyderabad|mumbai|delhi|noida|gurugram|chennai)\b/i.test(cleanLine)) kind = 'location';
      else if (extractSkillsFromText(cleanLine).length > 0) kind = 'skill';

      requirements.push({
        kind,
        value: cleanLine,
        mandatory,
        evidence: cleanLine
      });

      if (requirements.length >= 10) break; // Keep bounded
    }
  }

  // Fallback: If no explicit sections were parsed, scan for high-signal bullet points
  if (requirements.length === 0) {
    for (const line of lines) {
      const isBullet = /^[•\-\*\d+\.]\s+/.test(line);
      if (!isBullet) continue;
      const cleanLine = line.replace(/^[•\-\*\d+\.]\s+/, '').trim();
      const skillsInLine = extractSkillsFromText(cleanLine);
      if (skillsInLine.length > 0) {
        requirements.push({
          kind: 'skill',
          value: cleanLine,
          mandatory: /\b(?:must|required|mandatory|essential)\b/i.test(cleanLine),
          evidence: cleanLine
        });
        if (requirements.length >= 8) break;
      }
    }
  }

  return requirements;
}

function extractSkillsAndRequirements(text = '') {
  return {
    skills: extractSkillsFromText(text),
    requirements: extractRequirementsFromText(text)
  };
}

  const htmlToCleanText = function htmlToCleanText(html = '') {
  if (!html) return '';
  let text = String(html)
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(n));

  // Convert headings to Markdown
  text = text.replace(/<h[1-6][^>]*>(.*?)<\/h[1-6]>/gi, '\n\n### $1\n\n');
  // Convert list items to Markdown bullets
  text = text.replace(/<li[^>]*>(.*?)<\/li>/gi, '\n- $1');
  // Convert paragraphs and line breaks
  text = text.replace(/<p[^>]*>/gi, '\n\n');
  text = text.replace(/<\/p>/gi, '');
  text = text.replace(/<br\s*\/?>/gi, '\n');
  // Strip remaining HTML tags
  text = text.replace(/<[^>]+>/g, ' ');
  // Clean whitespace
  text = text.replace(/[ \t]+/g, ' ');
  text = text.replace(/\n\s*\n\s*\n+/g, '\n\n');
  return text.trim();
};
  const isIndiaOrRemoteLocation = function isIndiaOrRemoteLocation(location = '') {
  if (!location) return true;
  const normLoc = String(location).toLowerCase();
  const isForeign = /\b(?:united states|usa|us\b|uk\b|united kingdom|london|san francisco|sf\b|seattle|austin|dublin|ireland|germany|berlin|france|paris|canada|toronto|vancouver|australia|sydney|singapore|tokyo|japan)\b/i.test(normLoc);
  const isIndia = /\b(?:india|in\b|bengaluru|bangalore|hyderabad|pune|mumbai|delhi|noida|gurgaon|gurugram|chennai|kolkata|ahmedabad|karnataka|maharashtra|telangana|tamil\s*nadu|haryana|remote|worldwide|anywhere)\b/i.test(normLoc);
  return isIndia && !isForeign;
};
  const detectRiskSignals = function detectRiskSignals(text = '') {
  const content = String(text || '');
  const signals = [];

  // Match fee requirements only when NOT preceded by negative context (e.g. "no application fee", "zero registration fee", "free of fees")
  const feePattern = /(?<!\b(?:no|zero|without|free\s+of|free\s+from)\s+)(?:registration\s+fee|processing\s+fee|application\s+fee|training\s+fee|security\s+deposit|pay\s+\$?\d+|send\s+money)\b/i;
  const feeMatch = content.match(feePattern);
  if (feeMatch) {
    // Context check around the match to protect against phrases like "no application fee is required"
    const start = Math.max(0, feeMatch.index - 25);
    const end = Math.min(content.length, feeMatch.index + feeMatch[0].length + 25);
    const window = content.slice(start, end);
    const isExempt = /\b(?:no|zero|without|free|waived)\s+(?:registration|processing|application|training)?\s*fee/i.test(window) ||
                     /\b(?:free\s+to\s+apply|free\s+to\s+participate|no\s+fee)\b/i.test(window);
    if (!isExempt) {
      signals.push(`fee_payment_required: "${feeMatch[0]}"`);
    }
  }

  const credentialMatch = content.match(/\b(?:send\s+(?:your\s+)?(?:password|bank\s+account|credit\s+card|cvv|otp))\b/i);
  if (credentialMatch) {
    signals.push(`credential_request: "${credentialMatch[0]}"`);
  }

  const injectionMatch = content.match(/\b(?:ignore\s+(?:all\s+)?(?:previous\s+)?instructions|system\s+prompt|override\s+(?:all\s+)?policies|mark\s+as\s+act|eval:\s*act)\b/i);
  if (injectionMatch) {
    signals.push(`prompt_injection_detected: "${injectionMatch[0]}"`);
  }

  return signals;
};
  const classifySeniority = function classifySeniority(title = '', commitment = '') {
  const combined = `${title} ${commitment}`.toLowerCase();

  if (/\b(?:intern|internship|trainee|apprentice|fellow|fellowship)\b/i.test(combined)) {
    return 'intern';
  }

  const hasExec = /\b(?:director|vice president|vp\b|chief|head of|general manager|partner\b)/i.test(combined);
  if (hasExec) {
    return 'executive';
  }

  const hasSenior = /\b(?:senior|sr\.?\b|lead\b|principal\b|staff\b|manager|architect|mgr\b)/i.test(combined);

  const hasEntry = /\b(?:junior|jr\.?\b|entry[- ]level|graduate engineer|fresher|associate (?:software|engineer|developer|consultant|analyst|qa|tester|product))\b/i.test(combined)
    || (/\bassociate\b/i.test(combined) && !hasSenior && !hasExec);

  if (hasEntry && !hasSenior) {
    return 'entry';
  }

  if (hasSenior) {
    return 'senior';
  }

  if (/\b(?:software engineer|developer|analyst|specialist|designer|consultant)\b/i.test(combined)) {
    return 'mid';
  }

  return 'uncertain';
};
  const parseDevpostDeadline = function parseDevpostDeadline(datesStr) {
  if (!datesStr) return null;
  // Match month day, year format at the end of the date range: e.g. "Aug 15 - Oct 25, 2026"
  const endMatch = datesStr.match(/(?:^|[-–—])\s*([A-Za-z]{3})\s+(\d{1,2}),\s+(\d{4})\s*$/);
  const fallback = datesStr.match(/([A-Za-z]{3})\s+(\d{1,2}),\s+(\d{4})/g);
  const target = endMatch ? endMatch[0] : (fallback ? fallback[fallback.length - 1] : null);
  if (!target) return null;

  const parts = target.match(/([A-Za-z]{3})\s+(\d{1,2}),\s+(\d{4})/);
  if (!parts) return null;

  const [_, monthStr, dayStr, yearStr] = parts;
  const months = {
    jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
    jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11
  };
  const m = months[monthStr.toLowerCase()];
  if (m === undefined) return null;

  const d = parseInt(dayStr, 10);
  const y = parseInt(yearStr, 10);
  if (y < 2000 || y > 2100) return null;

  const dateObj = new Date(Date.UTC(y, m, d));
  // Strict calendar verification: month and day must match exactly (prevent rollover)
  if (dateObj.getUTCFullYear() !== y || dateObj.getUTCMonth() !== m || dateObj.getUTCDate() !== d) {
    return null;
  }
  return dateObj.toISOString().slice(0, 10);
};
  const helper = function normalizeLeverItem(company, item) {
  if (!item || !item.id || !item.text) {
    throw new Error('INVALID_LEVER_PAYLOAD: Missing id or title');
  }

  const title = String(item.text).trim();
  const location = item.categories?.location || item.categories?.allLocations?.join(', ') || null;
  const commitment = item.categories?.commitment || '';
  const team = item.categories?.team || item.categories?.department || null;
  const originalUrl = item.hostedUrl || `https://jobs.lever.co/${company}/${item.id}`;
  const applyUrl = item.applyUrl || `${originalUrl}/apply`;

  // Infer type: strictly job or internship
  const isIntern = /\b(?:intern|internship|trainee|apprentice)\b/i.test(title + ' ' + commitment);
  const type = isIntern ? 'internship' : 'job';

  // Preserve substantive posting descriptions, requirements, and lists
  const descParts = [
    item.descriptionPlain || (item.description ? htmlToCleanText(item.description) : ''),
    item.additionalPlain || '',
    Array.isArray(item.lists)
      ? item.lists.map(l => `${l.text || ''}:\n${htmlToCleanText(l.content || '')}`).join('\n')
      : ''
  ].filter(Boolean).join('\n\n');

  const rawTextParts = [
    title,
    `Organization: ${company.toUpperCase()}`,
    location ? `Location: ${location}` : '',
    commitment ? `Commitment: ${commitment}` : '',
    team ? `Team: ${team}` : '',
    descParts,
    `Apply: ${applyUrl}`
  ].filter(Boolean);

  const rawText = rawTextParts.join('\n');
  const riskSignals = detectRiskSignals(rawText);
  const trustTier = riskSignals.length > 0 ? 'unverified' : 'corroborated';
  const seniority = classifySeniority(title, commitment);
  const { skills: extractedSkills, requirements: extractedReqs } = extractSkillsAndRequirements(descParts);

  return {
    contract_version: 'source-item-v2',
    visibility: 'public',
    source_kind: 'company_feed',
    adapter: 'lever-v1',
    external_id: String(item.id),
    title,
    organization: company.toUpperCase(),
    type,
    location,
    deadline: null, // Lever postings do not carry explicit closing dates
    original_url: originalUrl,
    application_url: applyUrl,
    trust_tier: trustTier,
    source_badge: `${company.toUpperCase()} Careers`,
    risk_signals: riskSignals,
    seniority_level: seniority,
    skills: extractedSkills,
    requirements: extractedReqs,
    content_hash: hashString(rawText),
    raw_text: rawText,
    fields: {
      title,
      organization: company.toUpperCase(),
      location,
      commitment,
      deadline: null,
      seniority_level: seniority,
      skills: extractedSkills,
      requirements: extractedReqs
    },
    field_provenance: [
      { field: 'title', kind: 'structured_field', json_pointer: '/text', value: title },
      { field: 'location', kind: 'structured_field', json_pointer: '/categories/location', value: location },
      { field: 'apply_url', kind: 'structured_field', json_pointer: '/applyUrl', value: applyUrl }
    ]
  };
};
  const prepare = function prepareDiscoveryBatch(source, response, normalize, collection) {
  const base = {run_id: source.run_id, lease_token: source.lease_token};
  const body = response?.body ?? response;
  const failed = response?.error || Number(response?.statusCode || 200) >= 400;
  const list = collection === 'array' ? body : body?.[collection];
  if (failed || !Array.isArray(list)) {
    return [{json: {...base, scan_error: 'SOURCE_FETCH_OR_FORMAT_FAILED', next_cursor: source.cursor_state || {offset: 0}}}];
  }
  const sorted = [...list].sort((a, b) => {
    const intern = x => /\b(intern|internship|trainee|apprentice)\b/i.test(`${x.title || x.text || ''} ${x.categories?.commitment || ''}`);
    return Number(intern(b)) - Number(intern(a));
  });
  const cursor = Math.max(0, Number(source.cursor_state?.offset) || 0);
  const offset = cursor >= sorted.length ? 0 : cursor;
  const batch = sorted.slice(offset, offset + 10);
  const next_cursor = {offset: offset + batch.length >= sorted.length ? 0 : offset + batch.length};
  if (!batch.length) return [{json: {...base, empty: true, next_cursor}}];
  try {
    return batch.map(item => ({json: {...base, item: normalize(item), next_cursor}}));
  } catch {
    // Keep the cursor so a malformed batch is retryable, never silently successful.
    return [{json: {...base, scan_error: 'SOURCE_ITEM_INVALID', next_cursor: source.cursor_state || {offset: 0}}}];
  }
};
  const source = $('Check claimed source').first().json;
  return prepare(source, $input.first().json, item => helper(source.config.company, item), 'array');

